export async function callTool(name, args = {}) {
  if (name !== 'catalog_search') {
    throw new Error('Unknown tool: ' + name);
  }

  // validate extra inputs
  const allowed = new Set(['query', 'offset', 'limit']);
  for (const k of Object.keys(args)) {
    if (!allowed.has(k)) {
      throw new Error('Unknown argument: ' + k);
    }
  }

  // query required, string
  if (typeof args.query !== 'string') {
    throw new Error('query must be a string');
  }

  let offset = args.offset === undefined ? 0 : args.offset;
  let limit = args.limit === undefined ? 2 : args.limit;

  if (!isInt(offset) || offset < 0) {
    throw new Error('offset must be a non-negative integer');
  }
  if (!isInt(limit) || limit < 1 || limit > 5) {
    throw new Error('limit must be an integer between 1 and 5');
  }

  const q = args.query.toLowerCase();
  const matches = CATALOG.filter(item => item.name.toLowerCase().includes(q));

  const slice = matches.slice(offset, offset + limit);
  const hasMore = offset + limit < matches.length;
  const nextOffset = hasMore ? offset + limit : null;

  const result = {
    results: slice,
  };
  if (hasMore) {
    result.next_offset = nextOffset;
  }

  return {
    content: [{ type: 'text', text: JSON.stringify(result) }],
  };
}
